-- Minimal authorized mobile projections; no tenant-state blob, Auth IDs or endpoints.
begin;
grant create on schema api to cluvo_command_owner;
create view internal.pwa_obligation_progress
with (security_invoker = true)
as
with ledger as (
  select
    entry.tenant_id,
    entry.obligation_id,
    coalesce(sum(entry.minutes_delta), 0)::bigint as confirmed_minutes,
    coalesce(sum(entry.minutes_delta) filter (
      where entry.performed_at < season.winter_cutoff_at
    ), 0)::bigint as confirmed_before_winter
  from app.hour_ledger_entries as entry
  join app.obligations as obligation
    on obligation.tenant_id = entry.tenant_id and obligation.id = entry.obligation_id
  join app.seasons as season
    on season.tenant_id = obligation.tenant_id and season.id = obligation.season_id
  group by entry.tenant_id, entry.obligation_id
), booking_rollup as (
  select
    booking.tenant_id,
    booking.obligation_id,
    coalesce(sum(booking.credit_minutes_snapshot) filter (
      where booking.state in ('booked', 'reconfirmation_required', 'transfer_pending')
    ), 0)::bigint as planned_minutes,
    coalesce(sum(booking.credit_minutes_snapshot) filter (
      where booking.state = 'performed_pending'
    ), 0)::bigint as pending_minutes,
    count(*) filter (
      where booking.state = 'performed_pending'
        and booking.starts_at_snapshot < season.winter_cutoff_at
    )::integer as pending_before_winter_count
  from app.bookings as booking
  join app.obligations as obligation
    on obligation.tenant_id = booking.tenant_id and obligation.id = booking.obligation_id
  join app.seasons as season
    on season.tenant_id = obligation.tenant_id and season.id = obligation.season_id
  group by booking.tenant_id, booking.obligation_id
), latest_appointment_coverage as (
  select distinct on (decision.tenant_id, decision.obligation_id, decision.appointment_id)
    decision.tenant_id,
    decision.obligation_id,
    decision.appointment_id,
    decision.effect,
    decision.starts_on,
    decision.ends_on
  from app.obligation_coverage_decisions as decision
  where decision.source_kind = 'volunteer_appointment'
  order by
    decision.tenant_id,
    decision.obligation_id,
    decision.appointment_id,
    decision.decision_revision desc
), coverage as (
  select
    latest.tenant_id,
    latest.obligation_id,
    bool_or(
      latest.effect = 'household_exempt'
      and latest.starts_on <= (statement_timestamp() at time zone tenant.timezone)::date
      and (latest.ends_on is null
        or latest.ends_on >= (statement_timestamp() at time zone tenant.timezone)::date)
    ) as structurally_covered
  from latest_appointment_coverage as latest
  join app.tenants as tenant on tenant.id = latest.tenant_id
  group by latest.tenant_id, latest.obligation_id
)
select
  obligation.tenant_id,
  obligation.id as obligation_id,
  obligation.season_id,
  obligation.assessed_household_id as household_id,
  obligation.base_target_minutes,
  obligation.effective_target_minutes,
  obligation.effective_winter_minutes,
  obligation.ledger_revision,
  coalesce(ledger.confirmed_minutes, 0) as confirmed_minutes,
  coalesce(ledger.confirmed_before_winter, 0) as confirmed_before_winter_minutes,
  coalesce(booking_rollup.planned_minutes, 0) as planned_minutes,
  coalesce(booking_rollup.pending_minutes, 0) as pending_minutes,
  coalesce(booking_rollup.pending_before_winter_count, 0) as pending_before_winter_count,
  coalesce(
    internal.open_obligation_blocker_count(obligation.tenant_id, obligation.id),
    0
  ) as open_dispute_count,
  coalesce(coverage.structurally_covered, false) as structurally_covered,
  case
    when coalesce(coverage.structurally_covered, false) then 0
    else greatest(0, obligation.effective_target_minutes - coalesce(ledger.confirmed_minutes, 0))
  end as remaining_minutes,
  case
    when coalesce(coverage.structurally_covered, false) then 0
    else greatest(0, obligation.effective_winter_minutes - coalesce(ledger.confirmed_before_winter, 0))
  end as winter_deficit_minutes,
  case
    when coalesce(coverage.structurally_covered, false) then 'fulfilled_structural'
    when coalesce(ledger.confirmed_minutes, 0) >= obligation.effective_target_minutes then 'fulfilled_minutes'
    when obligation.status = 'review_hold' then 'review_hold'
    else 'active'
  end as annual_state,
  case
    when coalesce(coverage.structurally_covered, false) then 'not_required'
    when coalesce(booking_rollup.pending_before_winter_count, 0) > 0
      or coalesce(
        internal.open_obligation_blocker_count(obligation.tenant_id, obligation.id),
        0
      ) > 0 then 'needs_review'
    when coalesce(ledger.confirmed_before_winter, 0) >= obligation.effective_winter_minutes
      then 'reached'
    else 'deficit'
  end as winter_state
from app.obligations as obligation
left join ledger
  on ledger.tenant_id = obligation.tenant_id and ledger.obligation_id = obligation.id
left join booking_rollup
  on booking_rollup.tenant_id = obligation.tenant_id
 and booking_rollup.obligation_id = obligation.id
left join coverage
  on coverage.tenant_id = obligation.tenant_id and coverage.obligation_id = obligation.id
where (select internal.can_access_obligation_progress(obligation.tenant_id, obligation.id)) or (select internal.has_permission(obligation.tenant_id,'report.season.view','tenant',obligation.tenant_id));

alter view internal.pwa_obligation_progress owner to cluvo_command_owner;
revoke all on internal.pwa_obligation_progress from public,anon,authenticated,service_role;
grant select on internal.pwa_obligation_progress to cluvo_command_owner;

create function internal.pwa_snapshot(p_tenant_id uuid,p_season_id uuid default null,p_household_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_person uuid;v_household uuid:=p_household_id;v_season uuid:=p_season_id;v_context jsonb;v_data jsonb;v_count integer;
begin
 if not internal.is_active_member(p_tenant_id) then raise exception using errcode='42501',message='FORBIDDEN';end if;
 v_person:=internal.current_person_id(p_tenant_id);if v_person is null then raise exception using errcode='42501',message='FORBIDDEN';end if;
 if v_household is not null and not internal.can_access_household(p_tenant_id,v_household,'base') then raise exception using errcode='42501',message='FORBIDDEN';end if;
 if v_household is null then select count(*),min(h.id::text)::uuid into v_count,v_household from app.households h where h.tenant_id=p_tenant_id and h.status<>'archived' and internal.can_access_household(p_tenant_id,h.id,'base');if v_count<>1 then v_household:=null;end if;end if;
 if v_season is not null and not exists(select 1 from app.seasons s where s.tenant_id=p_tenant_id and s.id=v_season) then raise exception using errcode='42501',message='FORBIDDEN';end if;
 if v_season is null then select count(*),min(s.id::text)::uuid into v_count,v_season from app.seasons s where s.tenant_id=p_tenant_id and s.status='active';if v_count<>1 then v_season:=null;end if;end if;
 select jsonb_build_object('tenant_id',t.id,'tenant_slug',t.slug,'tenant_name',t.name,'timezone',t.timezone,'person_id',v_person,'display_name',concat_ws(' ',p.given_name,p.family_name),'season_id',v_season,'household_id',v_household,
 'households',coalesce((select jsonb_agg(jsonb_build_object('id',h.id,'label',h.label,'version',h.version,'can_view_progress',internal.can_access_household(p_tenant_id,h.id,'view_progress'),'can_invite_executor',internal.can_access_household(p_tenant_id,h.id,'invite_executor'))) from app.households h where h.tenant_id=p_tenant_id and h.status<>'archived' and internal.can_access_household(p_tenant_id,h.id,'base')),'[]'),
 'seasons',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'status',s.status)) from app.seasons s where s.tenant_id=p_tenant_id),'[]'),
 'capabilities',jsonb_build_object('manage',exists(select 1 from app.committees c where c.tenant_id=p_tenant_id and internal.has_permission(p_tenant_id,'shift.manage','committee',c.id)), 'reports',internal.has_permission(p_tenant_id,'report.season.view','tenant',p_tenant_id),'finance',internal.has_permission(p_tenant_id,'finance.fund.manage','tenant',p_tenant_id) or internal.has_permission(p_tenant_id,'report.season.view','tenant',p_tenant_id),'team_manage',exists(select 1 from app.teams tm where tm.tenant_id=p_tenant_id and internal.has_permission(p_tenant_id,'team_task.manage','team',tm.id)),'committee',exists(select 1 from app.committees c where c.tenant_id=p_tenant_id and internal.has_permission(p_tenant_id,'committee.workspace.view','committee',c.id)))) into v_context from app.tenants t join app.persons p on p.tenant_id=t.id and p.id=v_person where t.id=p_tenant_id;
 v_data:=jsonb_build_object('context',v_context);
 v_data:=v_data||jsonb_build_object('market',coalesce((select jsonb_agg(q.row order by q.starts_at) from (
 select s.starts_at,jsonb_build_object('id',pos.id,'position_id',pos.id,'shift_id',s.id,'version',s.version,'title',s.title,'starts_at',s.starts_at,'ends_at',s.ends_at,'credit_minutes',s.credit_minutes,'task_type_version_id',s.type_version_id,'is_team_task',exists(select 1 from app.pwa_team_task_sources ts where ts.tenant_id=s.tenant_id and ts.shift_id=s.id),'can_book',s.starts_at>statement_timestamp(),'can_confirm',internal.has_permission(p_tenant_id,'attendance.confirm','committee',s.committee_id),'cancellation_deadline',s.starts_at-make_interval(mins=>s.cancellation_minutes),'cancellation_minutes',s.cancellation_minutes,'category_name',cat.name,'committee_id',s.committee_id,'committee_name',c.name,'location_name',l.name,'minimum_age',r.minimum_age,'qualification_name',qt.name,'buddy_allowed',coalesce(r.buddy_allowed,false),'instruction_version_id',iv.id,'instructions',iv.body,'team_id',cl.team_id,'allocation_id',a.id,'member_person_id',a.member_person_id,'counts_for_team',a.counts_for_team,
 'available',pos.state='open' and (s.booking_opens_at is null or s.booking_opens_at<=statement_timestamp()) and (s.booking_closes_at is null or s.booking_closes_at>statement_timestamp()) and not exists(select 1 from app.bookings b where b.tenant_id=p_tenant_id and b.position_id=pos.id and b.state not in ('cancelled','transferred'))) row
 from app.shifts s join app.shift_positions pos on pos.tenant_id=s.tenant_id and pos.shift_id=s.id join app.committees c on c.tenant_id=s.tenant_id and c.id=s.committee_id join app.task_categories cat on cat.tenant_id=s.tenant_id and cat.id=s.category_id left join app.locations l on l.tenant_id=s.tenant_id and l.id=s.location_id left join app.shift_requirements r on r.tenant_id=s.tenant_id and r.shift_id=s.id left join app.qualification_types qt on qt.tenant_id=r.tenant_id and qt.id=r.qualification_type_id
 left join app.pwa_allocations a on a.tenant_id=s.tenant_id and a.position_id=pos.id and a.state<>'released' left join app.pwa_clusters cl on cl.tenant_id=a.tenant_id and cl.id=a.cluster_id
 left join lateral(select i.id,i.body from app.pwa_instruction_versions i where i.tenant_id=s.tenant_id and i.shift_id=s.id order by i.revision desc limit 1)iv on true
 where s.tenant_id=p_tenant_id and s.state='published' and (s.starts_at>statement_timestamp() or exists(select 1 from app.bookings own where own.tenant_id=p_tenant_id and own.position_id=pos.id and (internal.pwa_owns_booking(p_tenant_id,own.id) or internal.has_permission(p_tenant_id,'attendance.confirm','committee',s.committee_id)))) and (a.id is null or internal.pwa_can_team(p_tenant_id,cl.team_id) or exists(select 1 from app.pwa_reserve_requests rr where rr.tenant_id=p_tenant_id and rr.allocation_id=a.id and rr.recipient_person_id=v_person and rr.state='requested'))
 )q),'[]'));
 v_data:=v_data||jsonb_build_object('executors',coalesce((select jsonb_agg(jsonb_build_object('person_id',p.id,'display_name',concat_ws(' ',p.given_name,p.family_name),'obligation_id',g.obligation_id,'version',p.version,'household_id',o.assessed_household_id,'verified',exists(select 1 from app.account_person_links l where l.tenant_id=p.tenant_id and l.person_id=p.id and l.revoked_at is null),'adult',p.birth_date_precision='day' and p.birth_date+interval '18 years'<=(statement_timestamp() at time zone (v_context->>'timezone'))::date,'can_execute',true)) from app.executor_obligation_grants g join app.persons p on p.tenant_id=g.tenant_id and p.id=g.person_id join app.obligations o on o.tenant_id=g.tenant_id and o.id=g.obligation_id where g.tenant_id=p_tenant_id and g.revoked_at is null and g.valid_from<=statement_timestamp() and (g.valid_until is null or g.valid_until>statement_timestamp()) and p.status='active' and o.status in ('active','review_hold','fulfilled') and internal.can_book_executor(p_tenant_id,p.id,g.obligation_id) and (v_season is null or o.season_id=v_season)),'[]'));
 v_data:=v_data||jsonb_build_object('bookings',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'version',b.version,'state',b.state,'personal_calendar',internal.pwa_owns_booking(p_tenant_id,b.id),'position_id',b.position_id,'shift_id',s.id,'title',coalesce(d.title_snapshot,s.title),'location_name',coalesce(d.location_snapshot,(select l.name from app.locations l where l.tenant_id=s.tenant_id and l.id=s.location_id)),'shift_version',s.version,'category_name',(select cat.name from app.task_categories cat where cat.tenant_id=s.tenant_id and cat.id=s.category_id),'is_team_task',exists(select 1 from app.pwa_team_task_sources ts where ts.tenant_id=s.tenant_id and ts.shift_id=s.id),'team_id',(select cl.team_id from app.pwa_allocations al join app.pwa_clusters cl on cl.tenant_id=al.tenant_id and cl.id=al.cluster_id where al.tenant_id=d.tenant_id and al.id=d.allocation_id),'executor_person_id',b.executor_person_id,'executor_name',concat_ws(' ',p.given_name,p.family_name),'obligation_id',b.obligation_id,'starts_at',b.starts_at_snapshot,'ends_at',b.ends_at_snapshot,'credit_minutes',b.credit_minutes_snapshot,'cancellation_deadline',b.cancellation_deadline_snapshot,'prepared_at',d.prepared_at,'instructions',d.instruction_body_snapshot,'allocation_id',d.allocation_id,'member_person_id',d.member_person_id,'household_id',o.assessed_household_id,'member_name',(select concat_ws(' ',mp.given_name,mp.family_name) from app.persons mp where mp.tenant_id=b.tenant_id and mp.id=d.member_person_id),'can_cancel',internal.pwa_owns_booking(p_tenant_id,b.id) and d.allocation_id is null and b.state in ('booked','reconfirmation_required') and statement_timestamp()<b.cancellation_deadline_snapshot,'can_replace',internal.pwa_owns_booking(p_tenant_id,b.id) and b.state in ('booked','transfer_pending','reconfirmation_required'),'can_prepare',internal.pwa_owns_booking(p_tenant_id,b.id) and d.id is not null and b.state in ('booked','transfer_pending','reconfirmation_required'),'can_feedback',internal.is_self_person(p_tenant_id,b.executor_person_id) and b.state='confirmed','replacement_requested',exists(select 1 from app.pwa_transfer_offers tf where tf.tenant_id=b.tenant_id and tf.booking_id=b.id and tf.state='open'),'can_confirm',internal.has_permission(p_tenant_id,'attendance.confirm','committee',s.committee_id) and b.state in ('booked','performed_pending') and b.current_attendance_decision_id is null and b.ends_at_snapshot<=statement_timestamp())) from app.bookings b join app.shift_positions pos on pos.tenant_id=b.tenant_id and pos.id=b.position_id join app.shifts s on s.tenant_id=pos.tenant_id and s.id=pos.shift_id join app.persons p on p.tenant_id=b.tenant_id and p.id=b.executor_person_id join app.obligations o on o.tenant_id=b.tenant_id and o.id=b.obligation_id left join app.pwa_booking_details d on d.tenant_id=b.tenant_id and d.booking_id=b.id where b.tenant_id=p_tenant_id and (internal.pwa_owns_booking(p_tenant_id,b.id) or internal.has_permission(p_tenant_id,'attendance.confirm','committee',s.committee_id)) and (v_season is null or o.season_id=v_season)),'[]'));
 v_data:=v_data||jsonb_build_object('teams',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'name',t.name,'version',t.version,'can_manage',internal.has_permission(p_tenant_id,'team_task.manage','team',t.id),'parent_name',(select string_agg(concat_ws(' ',tp.given_name,tp.family_name),', ' order by tp.id) from app.team_person_memberships pm join app.persons tp on tp.tenant_id=pm.tenant_id and tp.id=pm.person_id where pm.tenant_id=t.tenant_id and pm.team_id=t.id and pm.membership_kind='team_parent' and pm.starts_at<=statement_timestamp() and (pm.ends_at is null or pm.ends_at>statement_timestamp())),'members',coalesce((select jsonb_agg(jsonb_build_object('person_id',p.id,'version',p.version,'display_name',concat_ws(' ',p.given_name,p.family_name),'household_id',(select h.household_id from app.household_person_links h where h.tenant_id=p_tenant_id and h.person_id=p.id and h.starts_at<=statement_timestamp() and (h.ends_at is null or h.ends_at>statement_timestamp()) and internal.can_access_household(p_tenant_id,h.household_id,'view_progress') limit 1))) from app.team_person_memberships m join app.persons p on p.tenant_id=m.tenant_id and p.id=m.person_id where m.tenant_id=p_tenant_id and m.team_id=t.id and m.membership_kind='player' and m.starts_at<=statement_timestamp() and (m.ends_at is null or m.ends_at>statement_timestamp()) and (internal.has_permission(p_tenant_id,'team_task.manage','team',t.id) or internal.is_self_person(p_tenant_id,p.id) or exists(select 1 from app.household_person_links h where h.tenant_id=p_tenant_id and h.person_id=p.id and h.starts_at<=statement_timestamp() and (h.ends_at is null or h.ends_at>statement_timestamp()) and internal.can_access_household(p_tenant_id,h.household_id,'view_progress')))),'[]'))) from app.teams t where t.tenant_id=p_tenant_id and t.active and internal.pwa_can_team(p_tenant_id,t.id)),'[]'));
 v_data:=v_data||jsonb_build_object('allocations',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'version',a.version,'state',a.state,'personal_calendar',a.member_person_id=v_person or exists(select 1 from app.household_person_links hp where hp.tenant_id=a.tenant_id and hp.person_id=a.member_person_id and hp.starts_at<=statement_timestamp() and (hp.ends_at is null or hp.ends_at>statement_timestamp()) and internal.can_access_household(p_tenant_id,hp.household_id,'view_progress')),'cluster_id',cl.id,'cluster_version',cl.version,'ordinal',pos.ordinal,'booking_id',(select b.id from app.bookings b where b.tenant_id=a.tenant_id and b.position_id=a.position_id and b.state not in ('cancelled','transferred')),'booking_version',(select b.version from app.bookings b where b.tenant_id=a.tenant_id and b.position_id=a.position_id and b.state not in ('cancelled','transferred')),'booking_state',(select b.state from app.bookings b where b.tenant_id=a.tenant_id and b.position_id=a.position_id and b.state not in ('cancelled','transferred')),'executor_name',(select concat_ws(' ',p.given_name,p.family_name) from app.bookings b join app.persons p on p.tenant_id=b.tenant_id and p.id=b.executor_person_id where b.tenant_id=a.tenant_id and b.position_id=a.position_id and b.state not in ('cancelled','transferred')),'member_name',(select concat_ws(' ',p.given_name,p.family_name) from app.persons p where p.tenant_id=a.tenant_id and p.id=a.member_person_id),'can_request_reserve',a.state='assigned' and cl.assign_until<=statement_timestamp() and s.starts_at>statement_timestamp() and internal.has_permission(p_tenant_id,'team_task.manage','team',cl.team_id),'can_assign',internal.has_permission(p_tenant_id,'team_task.manage','team',cl.team_id) and a.state in ('reserved','assigned'),'can_choose',a.state in ('reserved','assigned') and (a.member_person_id is not null or (cl.mode='self' and cl.self_until>statement_timestamp())) and exists(select 1 from app.executor_obligation_grants eg join app.h