 v_data:=v_data||jsonb_build_object('goals',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'version',g.version,'team_id',g.team_id,'season_id',g.season_id,'member_person_id',g.member_person_id,'goal',g.goal,'reason',case when internal.has_permission(p_tenant_id,'team_task.manage','team',g.team_id) then g.reason end)) from app.pwa_team_goals g where g.tenant_id=p_tenant_id and internal.pwa_can_team(p_tenant_id,g.team_id) and (v_season is null or g.season_id=v_season)),'[]'));
