 v_data:=v_data||jsonb_build_object('progress',case when v_household is not null and v_season is not null and internal.can_access_household(p_tenant_id,v_household,'view_progress') then (select jsonb_build_object('effective_target_minutes',st.effective_target_minutes,'effective_winter_minutes',st.effective_winter_minutes,'confirmed_minutes',st.confirmed_minutes,'confirmed_before_winter_minutes',st.confirmed_before_winter_minutes,'planned_minutes',st.planned_minutes,'pending_minutes',st.pending_minutes,'remaining_minutes',st.remaining_minutes,'structurally_covered',st.structurally_covered) from internal.pwa_obligation_progress st where st.tenant_id=p_tenant_id and st.season_id=v_season and exists(select 1 from app.household_obligation_links hl where hl.tenant_id=st.tenant_id and hl.obligation_id=st.obligation_id and hl.household_id=v_household and hl.starts_at<=statement_timestamp() and (hl.ends_at is null or hl.ends_at>statement_timestamp())) and (select count(distinct hl.obligation_id) from app.household_obligation_links hl join app.obligations ob on ob.tenant_id=hl.tenant_id and ob.id=hl.obligation_id where hl.tenant_id=p_tenant_id and hl.household_id=v_household and ob.season_id=v_season and hl.starts_at<=statement_timestamp() and (hl.ends_at is null or hl.ends_at>statement_timestamp()))=1) end);
 v_data:=v_data||jsonb_build_object('qualification_types',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'name',q.name)) from app.qualification_types q where q.tenant_id=p_tenant_id),'[]'));
 v_data:=v_data||jsonb_build_object('distribution_proposals',coalesce((select jsonb_agg(internal.pwa_distribution(p_tenant_id,t.id,v_season)) from app.teams t where t.tenant_id=p_tenant_id and t.active and v_season is not null and internal.has_permission(p_tenant_id,'team_task.manage','team',t.id)),'[]'));
 v_data:=v_data||jsonb_build_object('team_credit_requests',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'version',r.version,'team_id',t.team_id,'season_id',src.season_id,'title',r.title,'starts_at',r.starts_at,'ends_at',r.ends_at,'requested_minutes',r.requested_minutes,'state',r.state,'referee_needed',r.referee_needed,'match_id',r.match_id,'can_review_match',r.referee_needed and r.state in ('requested','reviewing') and internal.has_permission(p_tenant_id,'match.review','team',t.team_id),'can_review_volunteer',r.state in ('requested','reviewing') and (not r.referee_needed or exists(select 1 from app.team_task_market_reviews mr where mr.tenant_id=r.tenant_id and mr.request_id=r.id and mr.request_version=r.version and mr.review_kind='match' and mr.outcome='approved')) and internal.has_permission(p_tenant_id,'team_task.market.approve','tenant',p_tenant_id),'can_publish',r.state='approved' and internal.has_permission(p_tenant_id,'team_task.market.publish','tenant',p_tenant_id),'approved_minutes',(select rv.approved_minutes from app.team_task_market_reviews rv where rv.tenant_id=r.tenant_id and rv.request_id=r.id and rv.request_version=r.version and rv.review_kind='volunteer' and rv.outcome='approved'),'match_reviewed',exists(select 1 from app.team_task_market_reviews rv where rv.tenant_id=r.tenant_id and rv.request_id=r.id and rv.request_version=r.version and rv.review_kind='match' and rv.outcome='approved'))) from app.team_task_market_requests r join app.team_tasks t on t.tenant_id=r.tenant_id and t.id=r.team_task_id left join app.pwa_team_task_sources src on src.tenant_id=r.tenant_id and src.request_id=r.id where r.tenant_id=p_tenant_id and (internal.pwa_can_team(p_tenant_id,t.team_id) or internal.has_permission(p_tenant_id,'team_task.market.approve','tenant',p_tenant_id) or internal.has_permission(p_tenant_id,'team_task.market.publish','tenant',p_tenant_id) or internal.has_permission(p_tenant_id,'match.review','team',t.team_id)) and (v_season is null or src.season_id=v_season)),'[]'));
 v_data:=v_data||jsonb_build_object('reserve_candidates',coalesce((select jsonb_agg(jsonb_build_object('allocation_id',a.id,'person_id',p.id,'name',concat_ws(' ',p.given_name,p.family_name),'suitable',true)) from app.pwa_allocations a join app.pwa_clusters cl on cl.tenant_id=a.tenant_id and cl.id=a.cluster_id join app.shift_positions pos on pos.tenant_id=a.tenant_id and pos.id=a.position_id join app.persons p on p.tenant_id=a.tenant_id join app.intake_profiles ip on ip.tenant_id=p.tenant_id and ip.person_id=p.id join app.intake_answers_versions iv on iv.tenant_id=ip.tenant_id and iv.profile_id=ip.id and iv.revision=ip.current_revision where a.tenant_id=p_tenant_id and a.state='assigned' and cl.assign_until<=statement_timestamp() and internal.has_permission(p_tenant_id,'team_task.manage','team',cl.team_id) and iv.answers->'reserve_willing'='true'::jsonb and internal.pwa_executor_fits(p_tenant_id,p.id,pos.shift_id)),'[]'));
 v_data:=v_data||jsonb_build_object('reserve_requests',coalesce((select jsonb_agg(jsonb_build_object('id',rr.id,'version',rr.version,'allocation_id',a.id,'position_id',pos.id,'shift_id',s.id,'title',s.title,'member_person_id',a.member_person_id,'can_book',a.state='assigned' and internal.pwa_executor_fits(p_tenant_id,v_person,s.id))) from app.pwa_reserve_requests rr join app.pwa_allocations a on a.tenant_id=rr.tenant_id and a.id=rr.allocation_id join app.shift_positions pos on pos.tenant_id=a.tenant_id and pos.id=a.position_id join app.shifts s on s.tenant_id=pos.tenant_id and s.id=pos.shift_id where rr.tenant_id=p_tenant_id and rr.recipient_person_id=v_person and rr.state='requested'),'[]'));
 v_data:=v_data||jsonb_build_object('actions',coalesce((select jsonb_agg(q.row order by q.due_at nulls last) from (
 select a.due_at,jsonb_build_object('id',a.id,'version',a.version,'action_kind',a.action_kind,'title',coalesce(c.title,t.title,'Persoonlijke actie'),'detail',a.action_kind,'card_id',a.card_id,'team_task_id',a.team_task_id,'due_at',a.due_at,'state',a.state,'source_path',case when a.card_id is not null then '/app/committees' else '/app/teams' end) row from app.personal_action_items a left join app.kanban_cards c on c.tenant_id=a.tenant_id and c.id=a.card_id left join app.team_tasks t on t.tenant_id=a.tenant_id and t.id=a.team_task_id where a.tenant_id=p_tenant_id and a.recipient_person_id=v_person and a.state='open'
 union all select cl.assign_until,jsonb_build_object('id',al.id,'version',al.version,'action_kind','choose_executor','title','Kies de uitvoerder voor een teamplaats','detail',s.title,'due_at',cl.assign_until,'state','open','source_path','/app/teams') from app.pwa_allocations al join app.pwa_clusters cl on cl.tenant_id=al.tenant_id and cl.id=al.cluster_id join app.shift_positions pos on pos.tenant_id=al.tenant_id and pos.id=al.position_id join app.shifts s on s.tenant_id=pos.tenant_id and s.id=pos.shift_id where al.tenant_id=p_tenant_id and al.state='assigned' and s.starts_at>statement_timestamp() and exists(select 1 from app.household_person_links l where l.tenant_id=al.tenant_id and l.person_id=al.member_person_id and l.starts_at<=statement_timestamp() and (l.ends_at is null or l.ends_at>statement_timestamp()) and internal.can_access_household(p_tenant_id,l.household_id,'book_for'))
 union all select null::timestamptz,jsonb_build_object('id',h.id,'version',h.version,'action_kind','accept_handover','title','Lees en accepteer je teamoverdracht','detail',t.name,'state','open','source_path','/app/teams') from app.pwa_handovers h join app.teams t on t.tenant_id=h.tenant_id and t.id=h.team_id where h.tenant_id=p_tenant_id and h.successor_person_id=v_person and h.state='ready'
 union all select b.starts_at_snapshot,jsonb_build_object('id',b.id,'version',b.version,'action_kind','prepare_booking','title','Bereid je dienst voor','detail',d.title_snapshot,'due_at',b.starts_at_snapshot,'state','open','source_path','/app/agenda') from app.bookings b join app.pwa_booking_details d on d.tenant_id=b.tenant_id and d.booking_id=b.id where b.tenant_id=p_tenant_id and internal.pwa_owns_booking(p_tenant_id,b.id) and b.state in ('booked','reconfirmation_required') and d.prepared_at is null and b.starts_at_snapshot>statement_timestamp()
 union all select o.expires_at,jsonb_build_object('id',o.id,'version',o.version,'action_kind','find_replacement','title','Regel een vervanger voor je dienst','detail',o.reason,'due_at',o.expires_at,'state','open','source_path','/app/tasks') from app.pwa_transfer_offers o where o.tenant_id=p_tenant_id and o.state='open' and internal.pwa_owns_booking(p_tenant_id,o.booking_id)
 )q),'[]'));
 v_data:=v_data||jsonb_build_object('suitability',coalesce((select jsonb_agg((jsonb_build_object('position_id',pos.id,'shift_id',s.id,'person_id',eg.person_id,'obligation_id',eg.obligation_id)||internal.pwa_suitability(p_tenant_id,pos.id,eg.person_id,eg.obligation_id))) from app.shifts s join app.shift_positions pos on pos.tenant_id=s.tenant_id and pos.shift_id=s.id join app.executor_obligation_grants eg on eg.tenant_id=s.tenant_id left join app.pwa_allocations a on a.tenant_id=pos.tenant_id and a.position_id=pos.id and a.state<>'released' left join app.pwa_clusters cl on cl.tenant_id=a.tenant_id and cl.id=a.cluster_id where s.tenant_id=p_tenant_id and s.state='published' and s.starts_at>statement_timestamp() and eg.revoked_at is null and internal.can_book_executor(p_tenant_id,eg.person_id,eg.obligation_id) and (a.id is null or internal.pwa_can_team(p_tenant_id,cl.team_id) or exists(select 1 from app.pwa_reserve_requests rr where rr.tenant_id=p_tenant_id and rr.allocation_id=a.id and rr.recipient_person_id=v_person and rr.state='requested'))),'[]'));
 v_data:=v_data||jsonb_build_object('receiving_teams',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'version',t.version,'name',t.name)) from app.teams t where t.tenant_id=p_tenant_id and t.active and internal.has_permission(p_tenant_id,'team_task.manage','team',t.id)),'[]'));
 v_data:=v_data||jsonb_build_object('reserve_preview',coalesce((select jsonb_agg(jsonb_build_object('position_id',pos.id,'shift_id',s.id,'can_reserve',s.starts_at>statement_timestamp() and pos.state='open' and internal.has_permission(p_tenant_id,'shift.manage','committee',s.committee_id) and not exists(select 1 from app.pwa_allocations a where a.tenant_id=pos.tenant_id and a.position_id=pos.id and a.state<>'released') and not exists(select 1 from app.bookings b where b.tenant_id=pos.tenant_id and b.position_id=pos.id and b.state not in('cancelled','transferred')),'reason',case when not internal.has_permission(p_tenant_id,'shift.manage','committee',s.committee_id) then 'FORBIDDEN' when s.starts_at<=statement_timestamp() then 'PAST' when exists(select 1 from app.pwa_allocations a where a.tenant_id=pos.tenant_id and a.position_id=pos.id and a.state<>'released') then 'RESERVED' when exists(select 1 from app.bookings b where b.tenant_id=pos.tenant_id and b.position_id=pos.id and b.state not in('cancelled','transferred')) then 'BOOKED' else 'FREE' end)) from app.shifts s join app.shift_positions pos on pos.tenant_id=s.tenant_id and pos.shift_id=s.id where s.tenant_id=p_tenant_id and s.state='published' and s.starts_at>statement_timestamp() and not exists(select 1 from app.pwa_team_task_sources src where src.tenant_id=s.tenant_id and src.shift_id=s.id)),'[]'));
 v_data:=v_data||jsonb_build_object('committee_clusters',coalesce((select jsonb_agg(distinct jsonb_build_object('id',cl.id,'version',cl.version,'team_id',cl.team_id,'committee_id',s.committee_id,'title',cl.title,'self_until',cl.self_until,'assign_until',cl.assign_until,'can_followup',not exists(select 1 from app.pwa_allocations xa join app.shift_positions xp on xp.tenant_id=xa.tenant_id and xp.id=xa.position_id join app.shifts xs on xs.tenant_id=xp.tenant_id and xs.id=xp.shift_id where xa.tenant_id=cl.tenant_id and xa.cluster_id=cl.id and not internal.has_permission(p_tenant_id,'shift.manage','committee',xs.committee_id)))) from app.pwa_clusters cl join app.pwa_allocations al on al.tenant_id=cl.tenant_id and al.cluster_id=cl.id join app.shift_positions pos on pos.tenant_id=al.tenant_id and pos.id=al.position_id join app.shifts s on s.tenant_id=pos.tenant_id and s.id=pos.shift_id where cl.tenant_id=p_tenant_id and cl.state='active' and internal.has_permission(p_tenant_id,'shift.manage','committee',s.committee_id)),'[]'));
 v_data:=v_data||jsonb_build_object('assignee_candidates',coalesce((select jsonb_agg(jsonb_build_object('committee_id',c.id,'person_id',p.id,'name',concat_ws(' ',p.given_name,p.family_name))) from app.committees c join app.persons p on p.tenant_id=c.tenant_id where c.tenant_id=p_tenant_id and internal.has_permission(p_tenant_id,'committee.workspace.manage','committee',c.id) and p.status='active' and internal.person_has_permission(p_tenant_id,p.id,'committee.workspace.view','committee',c.id)),'[]'));
 v_data:=v_data||jsonb_build_object('instruction_targets',coalesce((select jsonb_agg(jsonb_build_object('source_shift_id',source.id,'shift_id',target.id,'version',target.version,'title',target.title,'starts_at',target.starts_at)) from app.shifts source join app.shifts target on target.tenant_id=source.tenant_id and target.id<>source.id and target.committee_id=source.committee_id and target.category_id=source.category_id where source.tenant_id=p_tenant_id and source.state='published' and target.state='published' and target.starts_at>statement_timestamp() and internal.has_permission(p_tenant_id,'shift.manage','committee',source.committee_id) and (select array_agg(distinct cl.team_id order by cl.team_id) from app.pwa_allocations al join app.pwa_clusters cl on cl.tenant_id=al.tenant_id and cl.id=al.cluster_id join app.shift_positions pos on pos.tenant_id=al.tenant_id and pos.id=al.position_id where al.tenant_id=p_tenant_id and pos.shift_id=source.id and al.state<>'released') is not distinct from (select array_agg(distinct cl.team_id order by cl.team_id) from app.pwa_allocations al join app.pwa_clusters cl on cl.tenant_id=al.tenant_id and cl.id=al.cluster_id join app.shift_positions pos on pos.tenant_id=al.tenant_id and pos.id=al.position_id where al.tenant_id=p_tenant_id and pos.shift_id=target.id and al.state<>'released')),'[]'));

 v_data:=v_data||jsonb_build_object('people_metadata',coalesce((select jsonb_agg(jsonb_build_object('person_id',p.id,'adult',coalesce(p.birth_date_precision='day' and p.birth_date+interval '18 years'<=(statement_timestamp() at time zone (v_context->>'timezone'))::date,false),'age_band',case when p.birth_date_precision<>'day' or p.birth_date is null then 'unknown' when p.birth_date+interval '18 years'<=(statement_timestamp() at time zone (v_context->>'timezone'))::date then 'adult' when p.birth_date+interval '16 years'<=(statement_timestamp() at time zone (v_context->>'timezone'))::date then '16_plus' else 'under_16' end)) from app.persons p where p.tenant_id=p_tenant_id and (p.id=v_person or exists(select 1 from app.household_person_links hp where hp.tenant_id=p.tenant_id and hp.person_id=p.id and hp.household_id=v_household and hp.starts_at<=statement_timestamp() and (hp.ends_at is null or hp.ends_at>statement_timestamp()) and internal.can_access_household(p_tenant_id,hp.household_id,'base')) or exists(select 1 from app.executor_obligation_grants eg where eg.tenant_id=p.tenant_id and eg.person_id=p.id and internal.can_book_executor(p_tenant_id,p.id,eg.obligation_id)))),'[]'));
 v_data:=v_data||jsonb_build_object('ledger_history',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'minutes_delta',e.minutes_delta,'performed_at',e.performed_at,'posted_at',e.posted_at,'entry_kind',e.entry_kind,'booking_id',e.booking_id,'reverses_entry_id',e.reverses_entry_id,'correction_reason',e.correction_reason,'evidence_kind','canonical_ledger_record') order by e.posted_at,e.id) from app.hour_ledger_entries e join app.obligations o on o.tenant_id=e.tenant_id and o.id=e.obligation_id where e.tenant_id=p_tenant_id and o.season_id=v_season and exists(select 1 from app.household_obligation_links hl where hl.tenant_id=o.tenant_id and hl.obligation_id=o.id and hl.household_id=v_household and hl.starts_at<=statement_timestamp() and (hl.ends_at is null or hl.ends_at>statement_timestamp())) and (internal.can_access_obligation_progress(p_tenant_id,o.id) or internal.has_permission(p_tenant_id,'report.season.view','tenant',p_tenant_id))),'[]'));
 return v_data;
end;$$;
create function api.pwa_snapshot(p_tenant_id uuid,p_season_id uuid default null,p_household_id uuid default null) returns jsonb language sql stable security invoker set search_path='' as $$select internal.pwa_snapshot(p_tenant_id,p_season_id,p_household_id);$$;
alter function internal.pwa_snapshot(uuid,uuid,uuid) owner to cluvo_command_owner;
alter function api.pwa_snapshot(uuid,uuid,uuid) owner to cluvo_command_owner;
revoke all on function internal.pwa_snapshot(uuid,uuid,uuid),api.pwa_snapshot(uuid,uuid,uuid) from public,anon,authenticated,service_role;
grant execute on function internal.pwa_snapshot(uuid,uuid,uuid),api.pwa_snapshot(uuid,uuid,uuid) to authenticated;
-- Only a registered immutable document version can grant this additional
-- Storage read. This does not grant arbitrary private-path access.
create function internal.pwa_can_read_document_object(p_path text)
returns boolean language sql stable security definer set search_path='' as $$
 select internal.actor_has_active_session() and exists(select 1 from app.committee_document_versions v where v.storage_object_path=p_path and internal.is_active_member(v.tenant_id) and internal.can_person_view_document(v.tenant_id,internal.current_person_id(v.tenant_id),v.document_id));
$$;
do $storage$ begin if to_regclass('storage.objects') is null then raise warning 'Supabase Storage relations are absent; PWA registered document Storage policy was not installed in this database-only run';else execute $policy$create policy cluvo_pwa_document_read on storage.objects for select to authenticated using(bucket_id='cluvo-private' and internal.pwa_can_read_document_object(name))$policy$;end if;end;$storage$;
create function internal.pwa_document(p_tenant_id uuid,p_document_id uuid,p_revision integer default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare d app.committee_documents%rowtype;v app.committee_document_versions%rowtype;begin
 if not internal.actor_has_active_session() or not internal.is_active_member(p_tenant_id) or not internal.can_person_view_document(p_tenant_id,internal.current_person_id(p_tenant_id),p_document_id) then raise exception using errcode='42501',message='FORBIDDEN';end if;
 select * into strict d from app.committee_documents where tenant_id=p_tenant_id and id=p_document_id;
 select * into strict v from app.committee_document_versions where tenant_id=p_tenant_id and document_id=p_document_id and revision=coalesce(p_revision,d.current_revision);
 return jsonb_build_object('id',d.id,'title',d.title,'version',d.version,'revision',v.revision,'bucket','cluvo-private','object_path',v.storage_object_path,'mime_type',v.mime_type,'size_bytes',v.size_bytes,'sha256',encode(v.content_hash,'hex'));
end;$$;
create function api.pwa_document(p_tenant_id uuid,p_document_id uuid,p_revision integer default null) returns jsonb language sql stable security invoker set search_path='' as $$select internal.pwa_document(p_tenant_id,p_document_id,p_revision);$$;
alter function internal.pwa_can_read_document_object(text) owner to cluvo_command_owner;
alter function internal.pwa_document(uuid,uuid,integer) owner to cluvo_command_owner;
alter function api.pwa_document(uuid,uuid,integer) owner to cluvo_command_owner;
revoke all on function internal.pwa_can_read_document_object(text),internal.pwa_document(uuid,uuid,integer),api.pwa_document(uuid,uuid,integer) from public,anon,authenticated,service_role;
grant execute on function internal.pwa_can_read_document_object(text),internal.pwa_document(uuid,uuid,integer),api.pwa_document(uuid,uuid,integer) to authenticated;


create function internal.pwa_ledger_entry(p_tenant_id uuid,p_entry_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare e app.hour_ledger_entries%rowtype;begin
 if not internal.actor_has_active_session() or not internal.is_active_member(p_tenant_id) then raise exception using errcode='42501',message='FORBIDDEN';end if;
 select * into strict e from app.hour_ledger_entries where tenant_id=p_tenant_id and id=p_entry_id;
 if not internal.can_access_obligation_progress(p_tenant_id,e.obligation_id) and not internal.has_permission(p_tenant_id,'report.season.view','tenant',p_tenant_id) then raise exception using errcode='42501',message='FORBIDDEN';end if;
 return jsonb_build_object('id',e.id,'tenant_id',e.tenant_id,'obligation_id',e.obligation_id,'season_id',e.season_id,'booking_id',e.booking_id,'attendance_decision_id',e.attendance_decision_id,'entry_kind',e.entry_kind,'minutes_delta',e.minutes_delta,'performed_at',e.performed_at,'posted_at',e.posted_at,'reverses_entry_id',e.reverses_entry_id,'correction_reason',e.correction_reason,'evidence_kind','canonical_ledger_record');
end;$$;
create function api.pwa_ledger_entry(p_tenant_id uuid,p_entry_id uuid) returns jsonb language sql stable security invoker set search_path='' as $$select internal.pwa_ledger_entry(p_tenant_id,p_entry_id);$$;
alter function internal.pwa_ledger_entry(uuid,uuid) owner to cluvo_command_owner;
alter function api.pwa_ledger_entry(uuid,uuid) owner to cluvo_command_owner;
revoke all on function internal.pwa_ledger_entry(uuid,uuid),api.pwa_ledger_entry(uuid,uuid) from public,anon,authenticated,service_role;
grant execute on function internal.pwa_ledger_entry(uuid,uuid),api.pwa_ledger_entry(uuid,uuid) to authenticated;
create function internal.pwa_receiving_team_proposals(p_tenant_id uuid,p_season_id uuid,p_position_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare x record;teams jsonb;positions jsonb;begin
 if not internal.actor_has_active_session() or not internal.is_active_member(p_tenant_id) then raise exception using errcode='42501',message='FORBIDDEN';end if;
 if p_position_ids is null or cardinality(p_position_ids) not between 1 and 50 or (select count(distinct id) from unnest(p_position_ids)id)<>cardinality(p_position_ids) or not exists(select 1 from app.seasons z where z.tenant_id=p_tenant_id and z.id=p_season_id and z.status='active') then raise exception using errcode='22023',message='INVALID_SELECTION';end if;
 for x in select requested.id from unnest(p_position_ids)requested(id) loop
  if not exists(select 1 from app.shift_positions pos join app.shifts s on s.tenant_id=pos.tenant_id and s.id=pos.shift_id join app.seasons z on z.tenant_id=s.tenant_id and z.id=p_season_id join app.tenants club on club.id=s.tenant_id where pos.tenant_id=p_tenant_id and pos.id=x.id and pos.state='open' and s.state='published' and s.starts_at>statement_timestamp() and (s.starts_at at time zone club.timezone)::date>=z.starts_on and (s.ends_at at time zone club.timezone)::date<=z.ends_on and internal.has_permission(p_tenant_id,'shift.manage','committee',s.committee_id) and not exists(select 1 from app.pwa_allocations a where a.tenant_id=pos.tenant_id and a.position_id=pos.id and a.state<>'released') and not exists(select 1 from app.bookings b where b.tenant_id=pos.tenant_id and b.position_id=pos.id and b.state not in('cancelled','transferred'))) then raise exception using errcode='42501',message='SELECTION_NOT_FREE_OR_AUTHORIZED';end if;
 end loop;
 select jsonb_agg(jsonb_build_object('position_id',pos.id,'shift_id',s.id,'shift_version',s.version,'starts_at',s.starts_at,'ends_at',s.ends_at) order by s.starts_at,pos.id) into positions from app.shift_positions pos join app.shifts s on s.tenant_id=pos.tenant_id and s.id=pos.shift_id where pos.tenant_id=p_tenant_id and pos.id=any(p_position_ids);
 select coalesce(jsonb_agg(jsonb_build_object('team_id',t.id,'version',t.version,'name',t.name,'goal_total',coalesce((select sum(coalesce((select g.goal from app.pwa_team_goals g where g.tenant_id=p_tenant_id and g.team_id=t.id and g.season_id=p_season_id and (g.member_person_id=m.person_id or g.member_person_id is null) order by g.member_person_id nulls last limit 1),0)) from app.team_person_memberships m where m.tenant_id=p_tenant_id and m.team_id=t.id and m.membership_kind='player' and m.starts_at<=statement_timestamp() and (m.ends_at is null or m.ends_at>statement_timestamp())),0),'confirmed_count',coalesce((select sum(e.count_delta) from app.pwa_team_execution_entries e where e.tenant_id=p_tenant_id and e.team_id=t.id and e.season_id=p_season_id),0),'assigned_count',(select count(*) from app.pwa_allocations a join app.pwa_clusters c on c.tenant_id=a.tenant_id and c.id=a.cluster_id where a.tenant_id=p_tenant_id and c.team_id=t.id and c.season_id=p_season_id and a.counts_for_team and a.state='assigned'),'planned_count',(select count(*) from app.pwa_allocations a join app.pwa_clusters c on c.tenant_id=a.tenant_id and c.id=a.cluster_id join app.pwa_booking_details d on d.tenant_id=a.tenant_id and d.allocation_id=a.id join app.bookings b on b.tenant_id=d.tenant_id and b.id=d.booking_id where a.tenant_id=p_tenant_id and c.team_id=t.id and c.season_id=p_season_id and a.counts_for_team and b.state in ('booked','transfer_pending','reconfirmation_required','performed_pending')),'suitable_member_count',(select count(distinct m.person_id) from app.team_person_memberships m where m.tenant_id=p_tenant_id and m.team_id=t.id and m.membership_kind='player' and m.starts_at<=statement_timestamp() and (m.ends_at is null or m.ends_at>statement_timestamp()) and exists(select 1 from app.household_person_links h join app.household_obligation_links hl on hl.tenant_id=h.tenant_id and hl.household_id=h.household_id join app.executor_obligation_grants eg on eg.tenant_id=hl.tenant_id and eg.obligation_id=hl.obligation_id where h.tenant_id=p_tenant_id and h.person_id=m.person_id and h.starts_at<=statement_timestamp() and (h.ends_at is null or h.ends_at>statement_timestamp()) and hl.starts_at<=statement_timestamp() and (hl.ends_at is null or hl.ends_at>statement_timestamp()) and eg.revoked_at is null and not exists(select 1 from app.shift_positions pos where pos.tenant_id=p_tenant_id and pos.id=any(p_position_ids) and not internal.pwa_executor_fits(p_tenant_id,eg.person_id,pos.shift_id)))),'reason','Feitelijke teamdoelen, huidige bezetting en passende uitvoerders; de coördinator kiest.') order by t.name,t.id),'[]') into teams from app.teams t where t.tenant_id=p_tenant_id and t.active and internal.has_permission(p_tenant_id,'team_task.manage','team',t.id);
 return jsonb_build_object('teams',teams,'positions',positions,'read_at',statement_timestamp());
end;$$;
create function api.pwa_receiving_team_proposals(p_tenant_id uuid,p_season_id uuid,p_position_ids uuid[]) returns jsonb language sql stable security invoker set search_path='' as $$select internal.pwa_receiving_team_proposals(p_tenant_id,p_season_id,p_position_ids);$$;
alter function internal.pwa_receiving_team_proposals(uuid,uuid,uuid[]) owner to cluvo_command_owner;
alter function api.pwa_receiving_team_proposals(uuid,uuid,uuid[]) owner to cluvo_command_owner;
revoke all on function internal.pwa_receiving_team_proposals(uuid,uuid,uuid[]),api.pwa_receiving_team_proposals(uuid,uuid,uuid[]) from public,anon,authenticated,service_role;
grant execute on function internal.pwa_receiving_team_proposals(uuid,uuid,uuid[]),api.pwa_receiving_team_proposals(uuid,uuid,uuid[]) to authenticated;

revoke create on schema api from cluvo_command_owner;
commit;
